// Normaliza telefone pro formato que a Meta espera: só dígitos, com 55 na frente (ex: 5511999998888)
function normalizaTelefone(raw) {
  if (!raw) return '';
  let digitos = String(raw).replace(/\D/g, '');
  digitos = digitos.replace(/^0+/, '');

  // já tem código do país (55) e tamanho compatível (DDD + 8 ou 9 dígitos) -> mantém
  if (digitos.startsWith('55') && (digitos.length === 12 || digitos.length === 13)) {
    return digitos;
  }
  // não tem código do país (só DDD + número) -> adiciona 55 na frente
  if (digitos.length === 10 || digitos.length === 11) {
    return '55' + digitos;
  }
  return digitos;
}

const input = $input.first().json;

const nomeIndicado = (input.nome_indicado || '').trim();
const telefoneIndicado = normalizaTelefone(input.telefone_indicado);
const nomeIndicador = (input.nome_indicador || 'Não identificado').trim();
const telefoneIndicador = normalizaTelefone(input.telefone_indicador);

if (!nomeIndicado || !telefoneIndicado) {
  throw new Error('Não foi possível identificar nome e/ou telefone do indicado. Verifique nome_indicado/telefone_indicado recebidos.');
}

return [{
  json: {
    nome_indicado: nomeIndicado,
    telefone_indicado: telefoneIndicado,
    nome_indicador: nomeIndicador,
    telefone_indicador: telefoneIndicador,
    data_hora: new Date().toISOString()
  }
}];

